create table if not exists public.suppliers (id uuid primary key default gen_random_uuid(),name text not null,account_number text,phone text,email text,website text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.inventory_locations (id uuid primary key default gen_random_uuid(),name text not null,location_type text not null check(location_type in ('warehouse','truck','shop','other')),assigned_user_id uuid references public.users(id) on delete set null,active boolean not null default true,created_at timestamptz not null default now());
alter table public.inventory_items add column if not exists supplier_id uuid references public.suppliers(id) on delete set null;alter table public.inventory_items add column if not exists location_id uuid references public.inventory_locations(id) on delete set null;alter table public.inventory_items add column if not exists supplier_sku text;
create table if not exists public.purchase_orders (id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id),status text not null default 'draft' check(status in ('draft','submitted','partial','received','cancelled')),ordered_by uuid references public.users(id),ordered_at timestamptz,expected_at timestamptz,received_at timestamptz,notes text,created_at timestamptz not null default now());
create table if not exists public.purchase_order_items (id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.purchase_orders(id) on delete cascade,inventory_item_id uuid references public.inventory_items(id) on delete set null,description text not null,quantity numeric not null check(quantity>0),received_quantity numeric not null default 0 check(received_quantity>=0),unit_cost numeric not null default 0 check(unit_cost>=0),created_at timestamptz not null default now());
alter table public.suppliers enable row level security;alter table public.inventory_locations enable row level security;alter table public.purchase_orders enable row level security;alter table public.purchase_order_items enable row level security;
create policy "staff read suppliers" on public.suppliers for select to authenticated using(private.current_employee_role() in ('owner','manager','csr_dispatch','technician','accounting'));create policy "managers manage suppliers" on public.suppliers for all to authenticated using(private.current_employee_role() in ('owner','manager')) with check(private.current_employee_role() in ('owner','manager'));
create policy "staff read inventory locations" on public.inventory_locations for select to authenticated using(private.current_employee_role() in ('owner','manager','csr_dispatch','technician','accounting'));create policy "managers manage inventory locations" on public.inventory_locations for all to authenticated using(private.current_employee_role() in ('owner','manager')) with check(private.current_employee_role() in ('owner','manager'));
create policy "staff read purchase orders" on public.purchase_orders for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch'));create policy "managers manage purchase orders" on public.purchase_orders for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting')) with check(private.current_employee_role() in ('owner','manager','accounting'));
create policy "staff read purchase order items" on public.purchase_order_items for select to authenticated using(private.current_employee_role() in ('owner','manager','accounting','csr_dispatch'));create policy "managers manage purchase order items" on public.purchase_order_items for all to authenticated using(private.current_employee_role() in ('owner','manager','accounting')) with check(private.current_employee_role() in ('owner','manager','accounting'));
